-- ==========================================
-- SOURCE: src/00_create_tables.sql
-- ==========================================
-- 1. User Profiles Table (Linked to Supabase auth.users)
CREATE TABLE IF NOT EXISTS public.profiles (
    id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
    email TEXT,
    role TEXT NOT NULL DEFAULT 'viewer',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    display_name TEXT,
    requested_access BOOLEAN NOT NULL DEFAULT FALSE
);

-- 2. Bins Table (Current Bin State)
CREATE TABLE IF NOT EXISTS public.bins (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    lat DOUBLE PRECISION NOT NULL,
    long DOUBLE PRECISION NOT NULL,
    fill_level SMALLINT NOT NULL DEFAULT 0,
    time TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    battery_level SMALLINT NOT NULL DEFAULT 100,
    location TEXT,
    compost INT,
    recycle INT,
    landfill INT,
    zone TEXT,
    is_deactivated BOOLEAN DEFAULT FALSE
);

-- 3. Telemetry Logs Table (Time-Series Sensor Readings)
CREATE TABLE IF NOT EXISTS public.telemetry_logs (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    bin_id BIGINT NOT NULL REFERENCES public.bins(id) ON DELETE CASCADE,
    fill_level SMALLINT NOT NULL,
    time TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    battery_level SMALLINT NOT NULL,
    compost INT,
    recycle INT,
    landfill INT,
    is_manual BOOLEAN
);

-- ==========================================
-- SOURCE: src/01_rls_enable.sql
-- ==========================================
ALTER TABLE public.bins ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.telemetry_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;

-- ==========================================
-- SOURCE: src/02_is_admin.sql
-- ==========================================
-- 2. Create helper function to check admin role without RLS recursion
CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS boolean AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid() AND role = 'admin'
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ==========================================
-- SOURCE: src/03_bins_updater.sql
-- ==========================================
CREATE OR REPLACE FUNCTION update_bin_current_status()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  UPDATE public.bins
  SET
    fill_level = GREATEST(NEW.compost, NEW.recycle, NEW.landfill),
    time = NEW.time,
    battery_level = NEW.battery_level,
    compost = NEW.compost,
    recycle = NEW.recycle,
    landfill = NEW.landfill
  WHERE id = NEW.bin_id;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE TRIGGER after_sensor_ping
AFTER INSERT ON public.telemetry_logs
FOR EACH ROW
EXECUTE FUNCTION update_bin_current_status();

-- ==========================================
-- SOURCE: src/04_profile_appender.sql
-- ==========================================
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger AS $$
BEGIN
  INSERT INTO public.profiles (id, email, display_name, role)
  VALUES (
    new.id,
    new.email,
    split_part(new.email, '@', 1), -- Automatically sets "john" for john@csus.edu
    'viewer'                       -- Default role for all created users
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN new;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE PROCEDURE public.handle_new_user();

-- ==========================================
-- SOURCE: src/policies/profile_read_access.sql
-- ==========================================
CREATE POLICY "Allow authenticated users to read profiles"
ON public.profiles
FOR SELECT
TO authenticated
USING (auth.uid() = id OR public.is_admin());

-- ==========================================
-- SOURCE: src/policies/self_profile_updates.sql
-- ==========================================
CREATE POLICY "Users can update their own profile"
ON public.profiles
FOR UPDATE
TO authenticated
USING (auth.uid() = id)
WITH CHECK (
  auth.uid() = id 
  AND (
    -- Block non-admins from changing their own role column
    role = (SELECT role FROM public.profiles WHERE id = auth.uid())
    OR public.is_admin()
  )
);

-- ==========================================
-- SOURCE: src/policies/admin_update_access.sql
-- ==========================================
CREATE POLICY "Admins can update any profile"
ON public.profiles
FOR UPDATE
TO authenticated
USING (public.is_admin())
WITH CHECK (public.is_admin());

